import {travelWorkshop} from './travel-ui.js';
import {readRegionMap,REGION_PAGES,regionPixels,validateRegionEdits} from './region-map.js';
export function regionWorkshop(api){const $=s=>document.querySelector(s),esc=api.esc;let page=0,brush=0,pick=false,native,hash,draft,dirty=false;
 function storeDraft(){if(!dirty){status('No unsaved world-map changes.');return;}for(const [page,words]of Object.entries(draft.pages))if(words.every((word,i)=>word===native.pages[page][i]))delete draft.pages[page];for(const [id,row]of Object.entries(draft.locations))if(['name','x','y','width','height'].every(key=>row[key]===native.locations[id][key]))delete draft.locations[id];validateRegionEdits({[hash]:draft});api.change(()=>{api.project().regionMaps??={};if(Object.keys(draft.pages).length||Object.keys(draft.locations).length)api.project().regionMaps[hash]=structuredClone(draft);else delete api.project().regionMaps[hash];});dirty=false;status('World map saved to project. Export the edited ROM to use it in game.');}
 function status(s){if($('#regionStatus'))$('#regionStatus').textContent=s;}
 function open(){const session=api.session();if(!session)throw Error('Open the original ROM first.');hash=session.id;try{native=readRegionMap(session.reader,hash);}catch(e){api.modal('World map',`<p>${esc(e.message)}</p><p>This editor changes the Town Map shown in game. Map connections are edited in the map workspace.</p>`);return;}draft=structuredClone(api.project().regionMaps?.[hash]||{pages:{},locations:{}});dirty=false;show();}
 const cells=()=>draft.pages[page]||native.pages[page];
 function show(){const cols=native.width||30,rows=native.height||20,bytesPerTile=native.bpp===8?64:32,pageNames=native.pageNames||REGION_PAGES;api.modal('World map',`<p>Edit the native Town Map. Artwork, names and player-marker bounds save with your project. ${native.profile.engine==='emerald'?'Hoenn artwork uses an affine 8-bit tilemap. Fly and cursor editing still need their Emerald adapters.':'Fly landings and cursor selection are available in Spawn, Fly & cursor.'} Source: ${esc(native.profile.label)}.</p><button id="regionTravel" type="button" ${native.profile.engine==='emerald'?'hidden':''}>Spawn, Fly & cursor</button><label>Region<select id="regionPage">${pageNames.map((name,i)=>`<option value="${i}" ${i===page?'selected':''}>${name}</option>`).join('')}</select></label><div style="overflow:auto"><canvas id="regionCanvas" width="${cols*8}" height="${rows*8}" style="width:100%;min-width:240px;max-width:720px;image-rendering:pixelated;touch-action:none;border:2px solid #323746" aria-label="Town Map painting canvas"></canvas></div><div class="button-row"><button id="regionPick" type="button">Pick tile</button><button id="regionSave" type="button" class="primary">Save world map</button><button id="regionPNG" type="button">Export PNG</button><button id="regionReset" type="button">Restore this page</button></div><p id="regionStatus" role="status">Tap the map to paint. Pick a tile to copy its palette and flips.</p><div class="button-row"><label>Tile<input id="regionTile" type="number" min="0" max="${native.tiles.length/bytesPerTile-1}" value="${brush&1023}"></label><label>Palette<select id="regionPalette">${Array.from({length:native.paletteBanks||5},(_,i)=>`<option ${i===brush>>>12?'selected':''}>${i}</option>`).join('')}</select></label><label><input id="regionFlipX" type="checkbox" ${native.bpp===8?'disabled':''} ${brush&1024?'checked':''}>Flip horizontally</label><label><input id="regionFlipY" type="checkbox" ${native.bpp===8?'disabled':''} ${brush&2048?'checked':''}>Flip vertically</label></div><p>Tiles in the selected palette (tap to choose)</p><div style="max-height:160px;overflow:auto"><canvas id="regionAtlas" style="width:256px;image-rendering:pixelated" aria-label="Town Map tile picker"></canvas></div><label>Location name<input id="regionQuery" type="search" placeholder="Find a town or route"></label><div id="regionLocations"></div>`,()=>{if(dirty)storeDraft();},'Save and close');
 $('#regionTravel').onclick=()=>{if(dirty)storeDraft();travelWorkshop(api).open();};const canvas=$('#regionCanvas'),ctx=canvas.getContext('2d'),im=ctx.createImageData(cols*8,rows*8);let queued=false;const draw=()=>{regionPixels(native,cells(),im.data);ctx.putImageData(im,0,0);},scheduleDraw=()=>{if(queued)return;queued=true;(globalThis.requestAnimationFrame||((fn)=>setTimeout(fn,16)))(()=>{queued=false;if(canvas.isConnected)draw();});};draw();
 const controls=()=>{const tile=+$('#regionTile').value;if(!Number.isInteger(tile)||tile<0||tile>=native.tiles.length/bytesPerTile)return false;brush=native.bpp===8?tile:tile|(+$('#regionPalette').value<<12)|($('#regionFlipX').checked?1024:0)|($('#regionFlipY').checked?2048:0);return true;};
 const atlas=()=>{const c=$('#regionAtlas'),n=native.tiles.length/bytesPerTile;c.width=128;c.height=Math.ceil(n/16)*8;const a=c.getContext('2d'),im=a.createImageData(c.width,c.height),bank=+$('#regionPalette').value;for(let tile=0;tile<n;tile++)for(let j=0;j<64;j++){const byte=native.tiles[tile*bytesPerTile+(native.bpp===8?j:j>>1)],color=native.palettes[native.bpp===8?byte:bank*16+(j%2?byte>>4:byte&15)],at=((Math.floor(tile/16)*8+(j>>3))*128+tile%16*8+j%8)*4;im.data.set([...color,255],at);}a.putImageData(im,0,0);};atlas();$('#regionPalette').onchange=()=>{controls();atlas();};$('#regionAtlas').onclick=e=>{const r=e.currentTarget.getBoundingClientRect(),x=Math.floor((e.clientX-r.left)*128/r.width/8),y=Math.floor((e.clientY-r.top)*e.currentTarget.height/r.height/8),tile=y*16+x;if(tile<native.tiles.length/bytesPerTile){$('#regionTile').value=tile;controls();}};
 let down=false,last=null;const paint=e=>{const r=canvas.getBoundingClientRect(),x=Math.floor((e.clientX-r.left)*cols/r.width),y=Math.floor((e.clientY-r.top)*rows/r.height);if(x<0||x>=cols||y<0||y>=rows)return;const i=y*cols+x;if(pick){down=false;last=null;brush=cells()[i];$('#regionTile').value=brush&1023;$('#regionPalette').value=brush>>>12;$('#regionFlipX').checked=!!(brush&1024);$('#regionFlipY').checked=!!(brush&2048);pick=false;$('#regionPick').textContent='Pick tile';atlas();status('Tile '+(brush&1023)+' selected.');return;}if(!controls()){status('Choose a valid tile number.');return;}const previous=last||{x,y};draft.pages[page]??=[...native.pages[page]];const steps=Math.max(Math.abs(x-previous.x),Math.abs(y-previous.y));for(let j=0;j<=steps;j++){const cx=steps?Math.round(previous.x+(x-previous.x)*j/steps):x,cy=steps?Math.round(previous.y+(y-previous.y)*j/steps):y;draft.pages[page][cy*cols+cx]=brush;}last={x,y};dirty=true;scheduleDraw();status('Unsaved world-map changes.');};canvas.onpointerdown=e=>{e.preventDefault();if(down)return;down=true;last=null;canvas.setPointerCapture?.(e.pointerId);paint(e);};canvas.onpointermove=e=>{if(down)paint(e);};canvas.onpointerup=canvas.onpointercancel=canvas.onlostpointercapture=()=>{down=false;last=null;};
 $('#regionPick').onclick=()=>{pick=!pick;$('#regionPick').textContent=pick?'Tap a map tile…':'Pick tile';};$('#regionSave').onclick=storeDraft;$('#regionPage').onchange=()=>{page=+$('#regionPage').value;show();};$('#regionReset').onclick=()=>{delete draft.pages[page];dirty=true;draw();status('Source artwork restored in draft. Save to keep this change.');};$('#regionPNG').onclick=()=>{draw();return api.savePNG(canvas,'Town_Map_'+pageNames[page].replace(/[^a-z0-9]/gi,'_')+'.png').catch(api.error);};
 const list=()=>{const query=$('#regionQuery').value.toLowerCase();$('#regionLocations').innerHTML=native.locations.filter(row=>(draft.locations[row.id]?.name||row.name).toLowerCase().includes(query)).map(row=>`<button type="button" class="studio-record" data-region-location="${row.id}">${esc(draft.locations[row.id]?.name||row.name)}</button>`).join('');document.querySelectorAll('[data-region-location]').forEach(b=>b.onclick=()=>location(+b.dataset.regionLocation));};$('#regionQuery').oninput=list;list();
 }
 function location(id){const row=draft.locations[id]||native.locations[id],unplaced=!native.locations[id].width&&!native.locations[id].height;api.modal('Town Map location',`<p>Names are shared with native map labels. Bounds place the player marker; changing them does not move Fly landings or the cursor’s location hitboxes.</p><label>Name<input id="regionName" maxlength="40" value="${esc(row.name)}"></label>${[['x','X',row.x,0,native.profile.engine==='emerald'?27:29],['y','Y',row.y,0,native.profile.engine==='emerald'?14:19],['width','Width',row.width,unplaced?0:1,30],['height','Height',row.height,unplaced?0:1,20]].map(([key,label,n,min,max])=>`<label>${label}<input type="number" id="region_${key}" value="${n}" min="${min}" max="${max}"></label>`).join('')}<button id="regionBack" type="button">Back to world map</button>`,()=>{const edit={name:$('#regionName').value.trim()};for(const key of ['x','y','width','height'])edit[key]=+$('#region_'+key).value;const next=structuredClone(draft);next.locations[id]=edit;validateRegionEdits({[hash]:next});draft=next;dirty=true;storeDraft();},'Save location');$('#regionBack').onclick=show;}
 return{open};}
